// =============================================================================
// Nó Code (Run Once for All Items) — colocar LOGO APÓS o nó "Extract HTML Content"
// Entrada esperada: o HTML extraiu as linhas <tr> como array de strings.
//   - Se você usou Key="linhas" + Return Array, os valores estão em
//     item.json.linhas (array de strings "<td>..</td>..").
//   - Ajuste a linha CAMPO_LINHAS abaixo se o nome da sua key for outro.
// Saída: um item por processo, com as 26 colunas no formato do banco.
// =============================================================================

const CAMPO_LINHAS = 'linhas'; // <- nome da Key configurada no nó HTML

// Ordem das colunas no HTML. A 1a ("Id") é descartada (nao existe no banco).
// "Outro Número" (HTML) sera renomeado para "outroNumero" (banco).
const COLS = ["Id","Pasta","Tipo de processo","Classe","Cliente","Posição",
  "Grupo do Cliente","Parte contrária","Número do Processo","Outro Número",
  "Natureza","Tipo de Ação","Cidade","UF","Órgão","Data da distribuição",
  "Valor da Causa","Valor envolvido (contingência)","Valor da Condenação/Acordo",
  "Análise de Risco","Advogado Responsável","Etiquetas","Escritório responsável",
  "Data do cadastro","Data do encerramento","Data da baixa","Status"];

const DATAS = new Set([
  "Data da distribuição","Data do cadastro","Data do encerramento","Data da baixa"
]);

function decodeEntities(s){
  return s.replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>')
          .replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&nbsp;/g,' ')
          .replace(/&#(\d+);/g, (_,n)=>String.fromCharCode(parseInt(n,10)));
}
function limpa(s){
  const t = decodeEntities(String(s ?? '')).replace(/\s+/g,' ').trim();
  return t === '' ? null : t;
}
function dataBR(s){
  if(!s) return null;
  const m = s.match(/^(\d{2})\/(\d{2})\/(\d{4})/);  // dd/mm/yyyy [hh:mm:ss]
  return m ? `${m[3]}-${m[2]}-${m[1]}` : s;          // -> yyyy-mm-dd
}
function parseLinha(html){
  const celulas = [...html.matchAll(/<td[^>]*>([\s\S]*?)<\/td>/g)].map(m => m[1]);
  // Linha valida tem 27 celulas. Se vier diferente, marca para inspecao.
  const obj = {};
  COLS.forEach((col, i) => {
    if (col === "Id") return;            // descarta a coluna Id
    let v = limpa(celulas[i] ?? '');
    if (DATAS.has(col)) v = dataBR(v);
    const chave = (col === "Outro Número") ? "outroNumero" : col;
    obj[chave] = v;
  });
  return { obj, n: celulas.length };
}

// ---- coleta as strings de linha de todos os itens de entrada ----
let linhas = [];
for (const item of $input.all()) {
  const v = item.json[CAMPO_LINHAS];
  if (Array.isArray(v)) linhas = linhas.concat(v);
  else if (typeof v === 'string') linhas.push(v);
}

const saida = [];
let semPasta = 0, malformadas = 0;
for (const html of linhas) {
  if (typeof html !== 'string' || !/<td/i.test(html)) continue;
  const { obj, n } = parseLinha(html);
  if (n !== 27) malformadas++;           // conta linhas fora do padrao
  if (!obj.Pasta) { semPasta++; continue; } // Pasta e PK NOT NULL -> pula
  saida.push({ json: obj });
}

return saida;

// Datas no formato dd/mm/aaaa usado pela API de publicações
const hoje = new Date();
const dia = String(hoje.getDate()).padStart(2, '0');
const mes = String(hoje.getMonth() + 1).padStart(2, '0');
const ano = hoje.getFullYear();
const dataHoje = `${dia}/${mes}/${ano}`;

// Logins de consulta vêm de variáveis de ambiente (DJEN_LOGIN_1, DJEN_SENHA_1, ...).
// Nunca deixe credenciais escritas no código do workflow.
const logins = [];
for (let i = 1; i <= 10; i++) {
  const login = $env[`DJEN_LOGIN_${i}`];
  const senha = $env[`DJEN_SENHA_${i}`];
  if (login && senha) logins.push({ login, senha });
}
if (logins.length === 0) throw new Error('Nenhum login configurado (DJEN_LOGIN_1 / DJEN_SENHA_1)');

return logins.map(l => ({ json: { ...l, dataHoje, publicacoes: [] } }));

const https = require('https');
const item  = $input.item.json;
const login = item.login;
const senha = item.senha;

const BASE  = $env.DJEN_API_HOST;
const PATH  = '/api/publicacoes';
const token = Buffer.from(`${login}:${senha}`).toString('base64');

function requisicao(options, body) {
  return new Promise((resolve, reject) => {
    const req = https.request(options, res => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); }
        catch(e) { resolve([]); }
      });
    });
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}

let totalConsumido = 0;

while (true) {
  const lote = await requisicao({
    host:   BASE,
    path:   `${PATH}/ConsultarPublicacoes`,
    method: 'GET',
    headers: {
      'Authorization': `Basic ${token}`,
      'Content-Type':  'application/json',
    },
  });

  const dados = Array.isArray(lote) ? lote : [];
  if (dados.length === 0) break;

  totalConsumido += dados.length;

  const payload = JSON.stringify(dados.map(p => ({
    IdProcesso:          p.IdProcesso,
    CodigoTermoPesquisa: p.CodigoTermoPesquisa,
    CodigoDiario:        p.CodigoDiario,
    CodigoDivisaoDiario: p.CodigoDivisaoDiario,
    DataDiario:          p.DataDiario,
  })));

  await requisicao({
    host:   BASE,
    path:   `${PATH}/ConfirmarPublicacoes`,
    method: 'POST',
    headers: {
      'Authorization':  `Basic ${token}`,
      'Content-Type':   'application/json',
      'Content-Length': Buffer.byteLength(payload),
    },
  }, payload);

  if (dados.length < 50) break;
}

return { json: { ...item, filaConsumida: totalConsumido } };

const https = require('https');
const item  = $input.item.json;
const login = item.login;
const senha = item.senha;
const data  = item.dataHoje;

const BASE  = $env.DJEN_API_HOST;
const PATH  = '/api/publicacoes';
const token = Buffer.from(`${login}:${senha}`).toString('base64');

function requisicao(options) {
  return new Promise((resolve, reject) => {
    const req = https.request(options, res => {
      let raw = '';
      res.on('data', chunk => raw += chunk);
      res.on('end', () => {
        try { resolve(JSON.parse(raw)); }
        catch(e) { resolve([]); }
      });
    });
    req.on('error', reject);
    req.end();
  });
}

const dataEnc = encodeURIComponent(data);
const dados = await requisicao({
  host:   BASE,
  path:   `${PATH}/ConsultarPublicacoesPersonalizado?data=${dataEnc}`,
  method: 'GET',
  headers: {
    'Authorization': `Basic ${token}`,
    'Content-Type':  'application/json',
  },
});

const publicacoes = (Array.isArray(dados) ? dados : []).map(p => ({
  login,
  n_recorte:       p.N_RECORTE,
  processo:        p.NUMERO_PROCESSO,
  nome_pesquisado: p.NOME_PESQUISADO,
  orgao_tribunal:  p.ORGAO_TRIBUNAL,
  juizo:           p.JUIZO_SECRETARIA,
  jornal:          p.JORNAL,
  estado:          p.ESTADO,
  pagina:          p.PAGINA,
  data_publicacao: p.DATA_PUBLICACAO,
  data_divulgacao: p.DATA_DIVULGACAO,
  autor:           p.AUTOR,
  reu:             p.REU,
  texto:           p.PUBLICACAO,
}));

return { json: { ...item, publicacoes, total: publicacoes.length } };

const itens = $input.all();

const todasPublicacoes = [];
const resumo = [];

for (const item of itens) {
  const pubs = item.json.publicacoes || [];
  todasPublicacoes.push(...pubs);
  resumo.push({
    login:       item.json.login,
    encontradas: item.json.total || 0,
  });
}

const dataHoje   = itens[0]?.json?.dataHoje || '';
const totalGeral = todasPublicacoes.length;

return [{ json: { dataHoje, resumo, todasPublicacoes, totalGeral } }];

const p = $input.item.json;

return {
  json: {
    'Login':           p.login          || '',
    'Processo':        p.processo        || '',
    'Nome Pesquisado': p.nome_pesquisado || '',
    'Estado':          p.estado          || '',
    'Data Publicacao': p.data_publicacao || '',
    'Data Divulgacao': p.data_divulgacao || '',
    'Texto':           p.texto ? String(p.texto).substring(0, 32000) : '',
  }
};

return $input.all().map(item => {
  const vals = Object.values(item.json);
  return {
    json: {
      _numeroProcesso: String(vals[5] ?? '').trim(),
      _origem: 'supabase'
    }
  };
});

return $input.all().map(item => {
  const vals = Object.values(item.json);
  return {
    json: {
      _numeroProcesso: String(vals[5] ?? '').trim(),
      _origem: 'supabase'
    }
  };
});

const todos = $input.all();

const djenItems = todos.filter(i => i.json._origem === 'djen');
const supabaseItems = todos.filter(i => i.json._origem === 'supabase');

if (supabaseItems.length === 0) throw new Error('Item do Supabase não encontrado — verifique se o email do dia foi recebido');
if (djenItems.length === 0) throw new Error('Item do DJEN não encontrado — verifique se o email do dia foi recebido');

const numerosSupabase = new Set(
  supabaseItems.map(i => String(i.json._numeroProcesso ?? '').trim()).filter(Boolean)
);

const resultado = djenItems.filter(item => {
  const valsLimpos = Object.entries(item.json)
    .filter(([k]) => k !== '_origem')
    .map(([, v]) => v);
  const colB = String(valsLimpos[1] ?? '').trim();
  return colB && !numerosSupabase.has(colB);
});

if (resultado.length === 0) {
  throw new Error('Nenhum processo sem correspondência encontrado');
}

return resultado.map(item => {
  const { _origem, ...resto } = item.json;
  return { json: resto };
});

const TRIBUNAL_PREFIXES = [
  'TJDFT', // Tribunal de Justiça do DF (caso especial, checar antes do TJ genérico)
  'STJ',
  'STF',
  'TST',
  'TSE',
  'STM',
  'TRF',
  'TRT',
  'TRE',
  'TJM',   // Tribunal de Justiça Militar (checar antes do TJ genérico)
  'TJ',
  'CNJ'
];

function extractTribunal(valor) {
  if (!valor) return 'OUTROS';
  const str = String(valor).toUpperCase();

  for (const prefixo of TRIBUNAL_PREFIXES) {
    const regex = new RegExp('(^|[^A-Z])' + prefixo);
    if (regex.test(str)) {
      return prefixo;
    }
  }

  return 'OUTROS'; // não identificado
}

const JORNAL_FIELD = 'Jornal'; // ajuste se o nome real da coluna for diferente

return $input.all().map(item => {
  const tribunal = extractTribunal(item.json[JORNAL_FIELD]);
  return {
    json: {
      Tribunal: tribunal,
      ...item.json
    }
  };
});

return $input.all().map(item => {
  const vals = Object.values(item.json);
  return {
    json: {
      _numeroProcesso: String(vals[5] ?? '').trim(),
      _pasta: String(item.json['Pasta'] ?? '').trim(),
      _status: String(item.json['Status'] ?? '').trim(),
      _tipo: String(item.json['Tipo de processo'] ?? '').trim(),
      _origem: 'supabase'
    }
  };
});

const todos = $input.all();

const djenItems   = todos.filter(i => i.json._origem === 'djen');
const supabaseItems = todos.filter(i => i.json._origem === 'supabase');

if (supabaseItems.length === 0) throw new Error('Item do Supabase não encontrado');
if (djenItems.length   === 0) throw new Error('Item do DJEN não encontrado');

// Chave composta: número do processo + instância (TST ou originário)
const chave = (numero, isTST) => `${numero}|${isTST ? 'TST' : 'ORIGINARIO'}`;

// Processos baixados (não devem aparecer no relatório final)
const numerosBaixados = new Set(
  supabaseItems
    .filter(i => i.json._status === 'Baixado')
    .map(i => chave(i.json._numeroProcesso, i.json._tipo === 'Recurso'))
    .filter(Boolean)
);

// Mapa (processo + instância) -> Pasta
const pastaPorProcesso = new Map();
for (const i of supabaseItems) {
  if (i.json._numeroProcesso) {
    const isTST = i.json._tipo === 'Recurso';
    pastaPorProcesso.set(chave(i.json._numeroProcesso, isTST), i.json._pasta || '');
  }
}

console.log('Total DJEN:', djenItems.length);
console.log('Total Supabase (Baixado):', numerosBaixados.size);
console.log('Total Supabase (cadastrados):', pastaPorProcesso.size);

// Mantém apenas processos do DJEN que NÃO aparecem como Baixado (na mesma instância) no Supabase
const resultado = djenItems.filter(item => {
  const processo = String(item.json['Processo'] ?? '').trim();
  if (!processo) return false;
  return !numerosBaixados.has(chave(processo, item.json._isTST));
});

console.log('Sem correspondência (antes de remover duplicatas):', resultado.length);

if (resultado.length === 0) throw new Error('Nenhum processo sem correspondência encontrado');

// Remove duplicatas por processo + instância
const vistos = new Set();
const semDuplicatas = resultado.filter(item => {
  const processo = String(item.json['Processo'] ?? '').trim();
  const k = chave(processo, item.json._isTST);
  if (vistos.has(k)) return false;
  vistos.add(k);
  return true;
});

console.log('Total final (sem duplicatas):', semDuplicatas.length);

return semDuplicatas.map(item => {
  const { _origem, _isTST, ...resto } = item.json;
  const processo = String(item.json['Processo'] ?? '').trim();
  const pasta = pastaPorProcesso.get(chave(processo, item.json._isTST));
  return {
    json: {
      ...resto,
      Pasta: pasta || 'SEM CADASTRO'
    }
  };
});
